UPDATE t_distributed_lock
SET holder = #{newHolder}, lock_time = #{lockTime}, expire_time = #{expireTime}, version = version + 1
WHERE lock_key = #{lockKey} AND holder = #{oldHolder} AND version = #{version}

UPDATE t_distributed_lock
SET holder = '', expire_time = DATE_SUB(NOW(), INTERVAL 1 SECOND)
WHERE lock_key = #{lockKey} AND holder = #{holder}
